function v3_e1_evidence(T,out)
P=readtable(fullfile(out,'tables','E1_paired.csv'));good=P.comparable;den=sum(good);summary=struct('total_pairs',height(P),'comparable_pairs',den,'A_success_in_comparable',sum(good & strcmp(P.status_A,'SUCCESS')),'B_success_in_comparable',sum(good & strcmp(P.status_B,'SUCCESS')),'B_only_success',sum(good & ~strcmp(P.status_A,'SUCCESS') & strcmp(P.status_B,'SUCCESS')),'A_only_success',sum(good & strcmp(P.status_A,'SUCCESS') & ~strcmp(P.status_B,'SUCCESS')),'both_success',sum(good & strcmp(P.status_A,'SUCCESS') & strcmp(P.status_B,'SUCCESS')),'both_not_success',sum(good & ~strcmp(P.status_A,'SUCCESS') & ~strcmp(P.status_B,'SUCCESS')));paper_json(fullfile(out,'reports','E1_paired_statistics.json'),summary);
M=readtable(fullfile(out,'tables/E1_min_duration.csv'));M.A_observed=isfinite(M.A_shortest_tested_s);M.B_observed=isfinite(M.B_shortest_tested_s);M.A_minus_B_s=M.A_shortest_tested_s-M.B_shortest_tested_s;writetable(M,fullfile(out,'tables/E1_min_duration.csv'));
D=T(strcmp(T.status,'MODEL_DOMAIN_FAIL'),{'id','amplitude_deg','transition_s','cmg','actual_end_s','complete','simulation_aborted','reason','alpha_at_end_deg','error_message'});D.last_height_m=nan(height(D),1);D.last_speed_mps=nan(height(D),1);D.first_predictor_domain_rejection_s=nan(height(D),1);for k=1:height(D),folder=fullfile(out,'E1/cases',char(string(D.id(k))));F=readtable(fullfile(folder,'domain_diagnostics.csv'));D.last_height_m(k)=F.height_m(end);D.last_speed_mps(k)=F.V_mps(end);files=dir(fullfile(folder,'*_authority.mat'));if ~isempty(files),z=load(fullfile(folder,files(1).name));for j=1:numel(z.diagnostics),info=z.diagnostics{j};text='';for key={'failure','fallback_reason','early_stop_reason'},if isfield(info,key{1}),text=[text ' ' info.(key{1})];end;end;if contains(lower(text),{'alpha outside','alpharange','atmosphere','height outside'}),D.first_predictor_domain_rejection_s(k)=z.control_times(j);break;end;end;end;end;writetable(D,fullfile(out,'tables/E1_domain_failures.csv'));
% Fixed rule declared before completion: ascending amplitude, then transition; first matching pair.
[~,order]=sortrows([P.amplitude_deg P.transition_s],[1 2]);P=P(order,:);kinds={'B_only','both_success','domain'};selected={};
for j=1:3
 switch j,case 1,mask=P.comparable & ~strcmp(P.status_A,'SUCCESS') & strcmp(P.status_B,'SUCCESS');case 2,mask=P.comparable & strcmp(P.status_A,'SUCCESS') & strcmp(P.status_B,'SUCCESS');case 3,mask=strcmp(P.status_A,'MODEL_DOMAIN_FAIL') | strcmp(P.status_B,'MODEL_DOMAIN_FAIL');end
 k=find(mask,1);if isempty(k),continue;end;pair=char(string(P.pair_id(k)));selected{end+1}=struct('type',kinds{j},'pair_id',pair);f=figure('Visible','off');tiledlayout(6,1);
 for arm={'A','B'},id=[pair '_' arm{1}];folder=fullfile(out,'E1','cases',id);D=readtable(fullfile(folder,'timeseries.csv'));path=fullfile(folder,'actuator_timeseries_20ms.csv');if ~isfile(path),z=load(fullfile(folder,'sim_output.mat'));s=jsondecode(fileread(fullfile(folder,'case_config.json')));v3_actuator_export(z.r,s,folder);end;A=readtable(path);c=v3_color('MPC',strcmp(arm{1},'B'));idx=1:max(1,ceil(height(D)/2500)):height(D);label=arm{1};
 nexttile(1);hold on;plot(D.time_s(idx),D.pitch_deg(idx),'Color',c,'DisplayName',label);if strcmp(label,'A'),plot(D.time_s(idx),D.ref_pitch_deg(idx),'k--','DisplayName','Reference');end
 nexttile(2);hold on;plot(D.time_s(idx),D.attitude_error_deg(idx),'Color',c,'DisplayName',label);
 nexttile(3);hold on;plot(A.time_s,rad2deg(A.elevator_actual_rad),'Color',c,'DisplayName',[label ' actual']);plot(A.time_s,rad2deg(A.elevator_command_rad),'--','Color',c,'DisplayName',[label ' command']);
 nexttile(4);hold on;plot(D.time_s(idx),D.alpha_deg(idx),'Color',c,'DisplayName',label);
 nexttile(5);hold on;if strcmp(label,'B'),plot(A.time_s,A.cmg_actual_y_Nm,'DisplayName','CMG pitch');nexttile(6);plot(A.time_s,max(abs(A{:,11:14}),[],2),'DisplayName','Max actual nu');end
 end
 labels={'Absolute pitch (deg)','Quaternion error (deg)','Elevator (deg)','True alpha (deg)','CMG pitch (Nm)','Max actual frame rate (rad/s)'};for row=1:6,nexttile(row);ylabel(labels{row});grid on;legend('Location','best');end;xlabel('Time (s)');sgtitle([strrep(pair,'_',' ') ': ' kinds{j}]);v3_savefig(f,out,['E1_boundary_' kinds{j}]);
end
paper_json(fullfile(out,'reports','E1_boundary_selection.json'),struct('rule','First pair in ascending amplitude then transition for B-only success, both-success, and model-domain status; missing categories explicitly absent','selected',{selected}));
f=fopen(fullfile(out,'reports','E1.md'),'a','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'\n共同完整可靠配对 %d/%d；其中A成功%d、B成功%d，B独有成功%d、A独有成功%d、共同成功%d、共同未通过%d。各自分母为共同配对数，不与全网格分母混用。\n\n边界图固定选择规则：按幅值、过渡时长升序，分别选择第一个B独有成功、共同成功、任一域外配对；没有该类时不另造案例。详见 E1_boundary_selection.json 和对应 E1_boundary_*.png。绝对俯仰与参考初态见各case的detail_metrics.json。\n',den,height(P),summary.A_success_in_comparable,summary.B_success_in_comparable,summary.B_only_success,summary.A_only_success,summary.both_success,summary.both_not_success);
end
